/**
 * Compile `bin/freva-addons.json` into one generated TypeScript module the Worker ships with.
 *
 * The pin file is the authority, and the point of compiling it in is WHERE the digests live: a
 * manifest served beside the wheels is written by whoever can replace the wheels, and a constant
 * inside the bundle is not. So the interpreter checks every artefact it downloads against a digest
 * that travelled with the code, and `prepare-addons` writes MANIFEST.json only as an operator
 * record. `--check` fails when the generated file has drifted; mirrors gen-python-sources.mjs.
 */
import { readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const HERE = dirname(fileURLToPath(import.meta.url));
const PINS = join(HERE, "..", "bin", "freva-addons.json");
const OUT = join(HERE, "..", "src", "worker", "addon-pins.generated.ts");

function render() {
  const raw = readFileSync(PINS, "utf8");
  const pins = JSON.parse(raw);
  const ids = Object.keys(pins.addons).sort();
  const body = JSON.stringify(pins.addons, null, 2)
    .split("\n")
    .map((line) => (line ? `  ${line}` : line))
    .join("\n");
  return [
    "/* GENERATED by scripts/gen-addon-pins.mjs from bin/freva-addons.json. Do not edit. */",
    "",
    "import type { AddonPins } from './addon-types.js';",
    "",
    "/** Every curated add-on, in the order the registry offers them. */",
    `export const ADDON_IDS = ${JSON.stringify(ids)} as const;`,
    "",
    "/** The pinned artefacts, with the digests a running interpreter checks against. */",
    `export const ADDON_PINS: AddonPins =\n${body} as unknown as AddonPins;`,
    "",
  ].join("\n");
}

const next = render();
if (process.argv.includes("--check")) {
  const current = (() => {
    try {
      return readFileSync(OUT, "utf8");
    } catch {
      return "";
    }
  })();
  if (current !== next) {
    console.error("addon-pins.generated.ts is out of date - run `npm run gen:addons`.");
    process.exit(1);
  }
  console.log("addon-pins.generated.ts is up to date");
} else {
  writeFileSync(OUT, next);
  console.log(`wrote ${OUT}`);
}
